import path from "node:path";import {mkdir,readFile,writeFile,unlink} from "node:fs/promises";import {randomUUID,createHash} from "node:crypto";import sharp from "sharp";import {detectImageType} from "./signature";
const root=path.resolve(process.env.STORAGE_ROOT||"storage/uploads");
export type StoredAsset={storageKey:string;previewKey:string;thumbnailKey:string;mimeType:string;sizeBytes:number;width:number;height:number;sha256:string};
function safe(key:string){const p=path.resolve(root,key);if(!p.startsWith(root+path.sep))throw new Error("Недопустимый путь");return p}
export async function storeImage(data:Buffer):Promise<StoredAsset>{if(data.length>15*1024*1024)throw new Error("Файл больше 15 МБ");const mimeType=detectImageType(data);const meta=await sharp(data).metadata();if(!meta.width||!meta.height)throw new Error("Изображение повреждено");const now=new Date(),base=`${now.getUTCFullYear()}/${String(now.getUTCMonth()+1).padStart(2,"0")}/${randomUUID()}`,keys={storageKey:`${base}/original.webp`,previewKey:`${base}/preview.webp`,thumbnailKey:`${base}/thumb.webp`};await mkdir(path.dirname(safe(keys.storageKey)),{recursive:true});await Promise.all([writeFile(safe(keys.storageKey),await sharp(data).rotate().webp({quality:92}).toBuffer()),writeFile(safe(keys.previewKey),await sharp(data).rotate().resize({width:1400,withoutEnlargement:true}).webp({quality:82}).toBuffer()),writeFile(safe(keys.thumbnailKey),await sharp(data).rotate().resize({width:600,withoutEnlargement:true}).webp({quality:78}).toBuffer())]);return{...keys,mimeType,sizeBytes:data.length,width:meta.width,height:meta.height,sha256:createHash("sha256").update(data).digest("hex")}}
export const readStored=(key:string)=>readFile(safe(key));
export async function writeStored(key:string,data:Buffer){const target=safe(key);await mkdir(path.dirname(target),{recursive:true});await writeFile(target,data)}
export async function deleteStored(key:string){try{await unlink(safe(key))}catch(error){if((error as NodeJS.ErrnoException).code!=="ENOENT")throw error}}
